BEGIN;

SET client_encoding = 'UTF8';

SET standard_conforming_strings = on;

SET check_function_bodies = false;

SET search_path = public, pg_catalog;

-- Tables
CREATE TABLE public."account_notifications" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "created_at" timestamp(6) with time zone NOT NULL,
    "detail" character varying(500) NOT NULL,
    "read" boolean NOT NULL,
    "target_url" character varying(300),
    "title" character varying(180) NOT NULL,
    "type" character varying(40) NOT NULL,
    "user_id" bigint NOT NULL
);

CREATE TABLE public."app_users" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "first_name" character varying(80) NOT NULL,
    "last_name" character varying(80) NOT NULL,
    "email" character varying(254) NOT NULL,
    "password_hash" character varying(100) NOT NULL,
    "description" text DEFAULT ''::text NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "country" character varying(80),
    "avatar_seed" character varying(80)
);

CREATE TABLE public."career_comments" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" bigint NOT NULL,
    "career_id" bigint NOT NULL,
    "content" jsonb NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "parent_id" bigint
);

CREATE TABLE public."career_outcomes" (
    "career_id" bigint NOT NULL,
    "outcome" text NOT NULL,
    "position" integer NOT NULL
);

CREATE TABLE public."career_ratings" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" bigint NOT NULL,
    "career_id" bigint NOT NULL,
    "value" smallint NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE public."careers" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" character varying(20) NOT NULL,
    "name" character varying(160) NOT NULL,
    "school_id" bigint NOT NULL,
    "duration_terms" smallint NOT NULL,
    "study_mode" character varying(12) NOT NULL,
    "status" character varying(8) DEFAULT 'ACTIVE'::character varying NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "image_url" character varying(600) NOT NULL,
    "description" text NOT NULL,
    "hero_summary" text,
    "overview" text,
    "professional_profile" text
);

CREATE TABLE public."comment_votes" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "created_at" timestamp(6) with time zone NOT NULL,
    "useful" boolean NOT NULL,
    "comment_id" bigint NOT NULL,
    "user_id" bigint NOT NULL
);

CREATE TABLE public."flyway_schema_history" (
    "installed_rank" integer NOT NULL,
    "version" character varying(50),
    "description" character varying(200) NOT NULL,
    "type" character varying(20) NOT NULL,
    "script" character varying(1000) NOT NULL,
    "checksum" integer,
    "installed_by" character varying(100) NOT NULL,
    "installed_on" timestamp without time zone DEFAULT now() NOT NULL,
    "execution_time" integer NOT NULL,
    "success" boolean NOT NULL
);

CREATE TABLE public."password_reset_tokens" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "created_at" timestamp(6) with time zone NOT NULL,
    "expires_at" timestamp(6) with time zone NOT NULL,
    "token_hash" character varying(64) NOT NULL,
    "used_at" timestamp(6) with time zone,
    "user_id" bigint NOT NULL
);

CREATE TABLE public."pensum_subjects" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "pensum_id" bigint NOT NULL,
    "subject_id" bigint NOT NULL,
    "term_number" smallint NOT NULL,
    "position" smallint NOT NULL,
    "mandatory" boolean DEFAULT true NOT NULL
);

CREATE TABLE public."pensums" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "career_id" bigint NOT NULL,
    "version" character varying(20) NOT NULL,
    "description" text NOT NULL,
    "effective_from" smallint NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE public."refresh_tokens" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "created_at" timestamp(6) with time zone NOT NULL,
    "expires_at" timestamp(6) with time zone NOT NULL,
    "revoked_at" timestamp(6) with time zone,
    "token_hash" character varying(64) NOT NULL,
    "user_id" bigint NOT NULL
);

CREATE TABLE public."saved_careers" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "created_at" timestamp(6) with time zone NOT NULL,
    "career_id" bigint NOT NULL,
    "user_id" bigint NOT NULL
);

CREATE TABLE public."schools" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" character varying(120) NOT NULL,
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "image_url" character varying(600) NOT NULL,
    "description" text NOT NULL
);

CREATE TABLE public."subject_prerequisites" (
    "subject_id" bigint NOT NULL,
    "prerequisite_id" bigint NOT NULL
);

CREATE TABLE public."subjects" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" character varying(30) NOT NULL,
    "name" character varying(200) NOT NULL,
    "description" text NOT NULL,
    "credits" smallint NOT NULL,
    "weekly_hours" smallint NOT NULL
);

-- Primary keys, unique constraints, checks and exclusions
ALTER TABLE ONLY public."account_notifications"
ADD CONSTRAINT "account_notifications_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."app_users"
ADD CONSTRAINT "app_users_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."app_users"
ADD CONSTRAINT "uk_app_users_email" UNIQUE (email);

ALTER TABLE ONLY public."career_comments"
ADD CONSTRAINT "career_comments_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."career_outcomes"
ADD CONSTRAINT "career_outcomes_position_check" CHECK ("position" >= 0);

ALTER TABLE ONLY public."career_outcomes"
ADD CONSTRAINT "career_outcomes_pkey" PRIMARY KEY (career_id, "position");

ALTER TABLE ONLY public."career_ratings"
ADD CONSTRAINT "career_ratings_value_check" CHECK (
    value >= 1
    AND value <= 5
);

ALTER TABLE ONLY public."career_ratings"
ADD CONSTRAINT "career_ratings_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."career_ratings"
ADD CONSTRAINT "uk14cbknqyntjrpao29183kdwla" UNIQUE (user_id, career_id);

ALTER TABLE ONLY public."career_ratings"
ADD CONSTRAINT "uk_career_rating_user" UNIQUE (user_id, career_id);

ALTER TABLE ONLY public."careers"
ADD CONSTRAINT "ck_careers_duration" CHECK (duration_terms > 0);

ALTER TABLE ONLY public."careers"
ADD CONSTRAINT "ck_careers_status" CHECK (
    status::text = ANY (
        ARRAY[
            'ACTIVE'::character varying,
            'INACTIVE'::character varying
        ]::text []
    )
);

ALTER TABLE ONLY public."careers"
ADD CONSTRAINT "ck_careers_study_mode" CHECK (
    study_mode::text = ANY (
        ARRAY[
            'ON_CAMPUS'::character varying,
            'ONLINE'::character varying,
            'HYBRID'::character varying
        ]::text []
    )
);

ALTER TABLE ONLY public."careers"
ADD CONSTRAINT "careers_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."careers"
ADD CONSTRAINT "uk_careers_code" UNIQUE (code);

ALTER TABLE ONLY public."comment_votes"
ADD CONSTRAINT "comment_votes_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."comment_votes"
ADD CONSTRAINT "ukvffcdpe6xmdagi3lxch43hjb" UNIQUE (comment_id, user_id);

ALTER TABLE ONLY public."flyway_schema_history"
ADD CONSTRAINT "flyway_schema_history_pk" PRIMARY KEY (installed_rank);

ALTER TABLE ONLY public."password_reset_tokens"
ADD CONSTRAINT "password_reset_tokens_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."password_reset_tokens"
ADD CONSTRAINT "idx_password_reset_hash" UNIQUE (token_hash);

ALTER TABLE ONLY public."pensum_subjects"
ADD CONSTRAINT "pensum_subjects_position_check" CHECK ("position" > 0);

ALTER TABLE ONLY public."pensum_subjects"
ADD CONSTRAINT "pensum_subjects_term_number_check" CHECK (term_number > 0);

ALTER TABLE ONLY public."pensum_subjects"
ADD CONSTRAINT "pensum_subjects_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."pensum_subjects"
ADD CONSTRAINT "uk_pensum_subject" UNIQUE (pensum_id, subject_id);

ALTER TABLE ONLY public."pensums"
ADD CONSTRAINT "pensums_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."pensums"
ADD CONSTRAINT "pensums_career_id_key" UNIQUE (career_id);

ALTER TABLE ONLY public."refresh_tokens"
ADD CONSTRAINT "refresh_tokens_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."refresh_tokens"
ADD CONSTRAINT "uko2mlirhldriil2y7krapq4frt" UNIQUE (token_hash);

ALTER TABLE ONLY public."saved_careers"
ADD CONSTRAINT "saved_careers_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."saved_careers"
ADD CONSTRAINT "ukhr67ouy3e3qtsctbise44e1ec" UNIQUE (user_id, career_id);

ALTER TABLE ONLY public."schools"
ADD CONSTRAINT "schools_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."schools"
ADD CONSTRAINT "uk_schools_name" UNIQUE (name);

ALTER TABLE ONLY public."subject_prerequisites"
ADD CONSTRAINT "subject_prerequisites_pkey" PRIMARY KEY (subject_id, prerequisite_id);

ALTER TABLE ONLY public."subjects"
ADD CONSTRAINT "subjects_credits_check" CHECK (
    credits >= 1
    AND credits <= 6
);

ALTER TABLE ONLY public."subjects"
ADD CONSTRAINT "subjects_weekly_hours_check" CHECK (
    weekly_hours >= 1
    AND weekly_hours <= 12
);

ALTER TABLE ONLY public."subjects"
ADD CONSTRAINT "subjects_pkey" PRIMARY KEY (id);

ALTER TABLE ONLY public."subjects"
ADD CONSTRAINT "subjects_code_key" UNIQUE (code);

-- Foreign keys
ALTER TABLE ONLY public."account_notifications"
ADD CONSTRAINT "fk3glfwp3ro150qvyvp11clrpno" FOREIGN KEY (user_id) REFERENCES app_users (id);

ALTER TABLE ONLY public."career_comments"
ADD CONSTRAINT "career_comments_career_id_fkey" FOREIGN KEY (career_id) REFERENCES careers (id) ON DELETE CASCADE;

ALTER TABLE ONLY public."career_comments"
ADD CONSTRAINT "career_comments_user_id_fkey" FOREIGN KEY (user_id) REFERENCES app_users (id) ON DELETE CASCADE;

ALTER TABLE ONLY public."career_comments"
ADD CONSTRAINT "fkhwta1rimpyx344j63ouwvfel9" FOREIGN KEY (parent_id) REFERENCES career_comments (id);

ALTER TABLE ONLY public."career_outcomes"
ADD CONSTRAINT "fksjmcvqx72nlvayam7f0b6ng4w" FOREIGN KEY (career_id) REFERENCES careers (id);

ALTER TABLE ONLY public."career_ratings"
ADD CONSTRAINT "career_ratings_career_id_fkey" FOREIGN KEY (career_id) REFERENCES careers (id) ON DELETE CASCADE;

ALTER TABLE ONLY public."career_ratings"
ADD CONSTRAINT "career_ratings_user_id_fkey" FOREIGN KEY (user_id) REFERENCES app_users (id) ON DELETE CASCADE;

ALTER TABLE ONLY public."careers"
ADD CONSTRAINT "fk_careers_school" FOREIGN KEY (school_id) REFERENCES schools (id);

ALTER TABLE ONLY public."comment_votes"
ADD CONSTRAINT "fk761ql7r8gmb21fes9wkx0w1m1" FOREIGN KEY (user_id) REFERENCES app_users (id);

ALTER TABLE ONLY public."comment_votes"
ADD CONSTRAINT "fkg1ywek2xafpatj91149o5lhq0" FOREIGN KEY (comment_id) REFERENCES career_comments (id);

ALTER TABLE ONLY public."password_reset_tokens"
ADD CONSTRAINT "fkk4vaguhrxs5jl3lqtshglaxo8" FOREIGN KEY (user_id) REFERENCES app_users (id);

ALTER TABLE ONLY public."pensum_subjects"
ADD CONSTRAINT "pensum_subjects_pensum_id_fkey" FOREIGN KEY (pensum_id) REFERENCES pensums (id) ON DELETE CASCADE;

ALTER TABLE ONLY public."pensum_subjects"
ADD CONSTRAINT "pensum_subjects_subject_id_fkey" FOREIGN KEY (subject_id) REFERENCES subjects (id);

ALTER TABLE ONLY public."pensums"
ADD CONSTRAINT "pensums_career_id_fkey" FOREIGN KEY (career_id) REFERENCES careers (id) ON DELETE CASCADE;

ALTER TABLE ONLY public."refresh_tokens"
ADD CONSTRAINT "fkt72gijoak5yufxws745gwflis" FOREIGN KEY (user_id) REFERENCES app_users (id);

ALTER TABLE ONLY public."saved_careers"
ADD CONSTRAINT "fkcek42f76f2ointy8ftwtm43um" FOREIGN KEY (user_id) REFERENCES app_users (id);

ALTER TABLE ONLY public."saved_careers"
ADD CONSTRAINT "fkl2g0vvj13biea6k0aj9nte4gw" FOREIGN KEY (career_id) REFERENCES careers (id);

ALTER TABLE ONLY public."subject_prerequisites"
ADD CONSTRAINT "fk8vcc3x4jk5nyevql4tbg04rlx" FOREIGN KEY (prerequisite_id) REFERENCES subjects (id);

ALTER TABLE ONLY public."subject_prerequisites"
ADD CONSTRAINT "fki2pk0tltinduehdgkvotwwa2b" FOREIGN KEY (subject_id) REFERENCES subjects (id);

-- Non-constraint indexes
CREATE INDEX idx_career_comments_career_created ON public.career_comments USING btree (career_id, created_at DESC);

CREATE INDEX idx_career_ratings_career ON public.career_ratings USING btree (career_id);

CREATE INDEX idx_careers_name_lower ON public.careers USING btree (lower((name)::text));

CREATE INDEX idx_careers_school_id ON public.careers USING btree (school_id);

CREATE INDEX flyway_schema_history_s_idx ON public.flyway_schema_history USING btree (success);

CREATE INDEX idx_pensum_subjects_pensum ON public.pensum_subjects USING btree (pensum_id, term_number);

COMMIT;